def test_path_template_port_contract() -> None:
    assert "path_template" in PathTemplateNode().outputs, (
        "PathTemplateNode.outputs must declare the 'path_template' port"
    )
    assert "path_template" in PAYLOAD_PATH_KEYS["fs.write_file"], (
        "PAYLOAD_PATH_KEYS['fs.write_file'] must contain 'path_template'"
    )


# ---------------------------------------------------------------------------
# H5 — list_files output port matches extract_items conventions
# ---------------------------------------------------------------------------

_ALLOWED_LIST_FILES_PORTS = frozenset(
    {"items", "files", "file_refs", "input", "data"}
)


def test_list_files_output_port_in_extract_items_set() -> None:
    declared = set(ListFilesNode().outputs)
    overlap = declared & _ALLOWED_LIST_FILES_PORTS
    assert overlap, (
        f"access.list_files declares output ports {sorted(declared)}, "
        f"none of which are in {sorted(_ALLOWED_LIST_FILES_PORTS)}"
    )


